from PIL import Image

data_dir = 'data/web_scraped_small'
data_dir = pathlib.Path(data_dir).with_suffix('')

# Remove files with valid extensions but invalid image bytes
for p in data_dir.glob('*/*'):
    if p.is_file():
        try:
            with Image.open(p) as im:
                im.verify()
        except Exception:
            p.unlink()"}

